        CreateWorktreeRequest {
            workspace_id: "workspace-a".into(),
            worktree: identity.clone(),
            base_ref: None,
        },
    )
    .await
    .expect("create worktree");

    let initial = cmd_worktree_status(
        app.handle().clone(),
        app.state::<WorkspaceRegistry>(),
        WorktreeStatusRequest {
            workspace_id: "workspace-a".into(),
            worktree: identity.clone(),
        },
    )
